public static class MinStackHarness
{
    public static List<int> Run(string[] ops, int[][] args)
    {
        var stack = new MinStack();
        var results = new List<int>();
        for (var i = 0; i < ops.Length; i++)
        {
            if (ops[i] == "push") stack.Push(args[i][0]);
            else if (ops[i] == "pop") stack.Pop();
            else if (ops[i] == "top") results.Add(stack.Top());
            else if (ops[i] == "getMin") results.Add(stack.GetMin());
        }
        return results;
    }
}

